// Encounter table by zone
var ZONE_ENCOUNTERS = {
  office:    ['chatty_coworker', 'it_guy', 'broken_printer', 'hr_karen'],
  conf:      ['mandatory_meeting', 'hr_karen', 'chatty_coworker'],
  kitchen:   ['chatty_coworker', 'broken_printer'],
  elevator:  ['it_guy', 'micromanager'],
  boss_area: ['the_boss']
};

/* ── ITEMS ────────────────────────────────────────────────────────────── */
var ITEMS = {
  coffee:       { name: 'Coffee',        heal: 20, desc: 'Restores 20 Energy' },
  energy_drink: { name: 'Energy Drink',  heal: 40, desc: 'Restores 40 Energy' },
  donut:        { name: 'Donut',         heal: 10, desc: 'Restores 10 Energy' }
};

/* ── PLAYER ───────────────────────────────────────────────────────────── */
var player = {
  row: 1, col: 1,
  hp: 50, maxHp: 50,
  atk: 12, def: 5,
  level: 1, xp: 0, xpNext: 20,
  gold: 10,
  inventory: { coffee: 2, energy_drink: 0, donut: 1 },
  statusEffect: null,  // 'stunned' | 'debuffed' | 'weakened'
  statusTurns: 0
};

/* ── GAME STATE ───────────────────────────────────────────────────────── */
var screen = 'title';   // title | map | battle | levelup | gameover | win
var currentEnemy = null;
var battleLog = [];
var battleLocked = false;
var mapMessage = '';
var bossDefeated = false;
var stepsToEncounter = 0;
var phase2Triggered = false;

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function newStepsToEncounter() {
  stepsToEncounter = randomInt(3, 7);
}
newStepsToEncounter();

/* ── ZONE DETECTION ───────────────────────────────────────────────────── */
function zoneAt(r, c) {
  var ch = cellAt(r, c);
  if (ch === 'B') return 'boss_area';
  if (ch === 'C') return 'conf';
  if (ch === 'K') return 'kitchen';
  if (ch === 'E') return 'elevator';
  return 'office';
}

/* ── LEVEL UP ─────────────────────────────────────────────────────────── */
var LEVEL_TABLE = [
  null,
  { xp: 20,  hpGain: 8,  atkGain: 2, defGain: 1 },
  { xp: 45,  hpGain: 8,  atkGain: 2, defGain: 1 },
  { xp: 80,  hpGain: 10, atkGain: 3, defGain: 2 },
  { xp: 130, hpGain: 10, atkGain: 3, defGain: 2 },
  { xp: 200, hpGain: 12, atkGain: 4, defGain: 2 }
];

var lastLevelGains = {};

function checkLevelUp() {
  var next = LEVEL_TABLE[player.level];
  if (!next) return false;
  if (player.xp >= next.xp) {
    player.level++;
    player.maxHp += next.hpGain;
    player.hp = Math.min(player.hp + next.hpGain, player.maxHp);
    player.atk += next.atkGain;
    player.def += next.defGain;
    player.xpNext = LEVEL_TABLE[player.level] ? LEVEL_TABLE[player.level].xp : 999;
    lastLevelGains = next;
    return true;
  }
  return false;
}

/* ── MAP RENDER ───────────────────────────────────────────────────────── */
var TILE_COLORS = {
  '#': '#555', '.': '#002200', 'D': '#002200',
  'B': '#220000', 'C': '#000022', 'K': '#221100',
  'E': '#112200', 'W': '#002244', ' ': '#001100'
};

var VIEW_R = 8, VIEW_C = 14;

function renderMap() {
  var lines = [];
  for (var r = player.row - VIEW_R; r <= player.row + VIEW_R; r++) {
    var line = '';
    for (var c = player.col - VIEW_C; c <= player.col + VIEW_C; c++) {
      if (r === player.row && c === player.col) {
        line += '@';
      } else {
        var ch = cellAt(r, c);
        if (ch === 'W') line += 'W';
        else if (ch === 'B' && bossDefeated) line += '.';
        else line += ch;
      }
    }
    lines.push(line);
  }

  var hpPct = Math.max(0, Math.round(player.hp / player.maxHp * 100));
  var xpToNext = player.xpNext - player.xp;

  var statusHtml = '';
  if (player.statusEffect) {
    statusHtml = '<span class="status-effect"> [' + player.statusEffect.toUpperCase() + ']</span>';
  }

  var invParts = [];
  Object.keys(ITEMS).forEach(function(k) {
    if (player.inventory[k] > 0) {
      invParts.push(ITEMS[k].name + 'x' + player.inventory[k]);
    }
  });

  w.html(
    '<div class="game-container">' +
    '<div class="map-screen">' +
    '<div class="map-grid">' + lines.join('\n') + '</div>' +
    '<div class="status-bar">' +
      'LVL:<span>' + player.level + '</span> ' +
      'HP:<span>' + player.hp + '/' + player.maxHp + '</span> ' +
      '<div class="hp-bar"><div class="hp-fill" style="width:' + hpPct + '%"></div></div> ' +
      'XP:<span>' + player.xp + '/' + player.xpNext + '</span> ' +
      'G:<span>$' + player.gold + '</span>' +
      statusHtml +
    '</div>' +
    '<div class="status-bar" style="font-size:11px;color:#777;">' +
      (invParts.length ? 'Items: ' + invParts.join(' | ') : 'No items') +
      ' &nbsp; [Arrow keys to move, I=use item, H=heal]' +
    '</div>' +
    '<div class="map-message">' + mapMessage + '</div>' +
    '</div></div>'
  );
}

/* ── BATTLE RENDER ────────────────────────────────────────────────────── */
function renderBattle() {
  var e = currentEnemy;
  var hpPct = Math.max(0, Math.round(e.hp / e.maxHp * 100));
  var phpPct = Math.max(0, Math.round(player.hp / player.maxHp * 100));

  var statusHtml = player.statusEffect
    ? '<span class="status-effect"> [' + player.statusEffect.toUpperCase() + ']</span>' : '';

  var logText = battleLog.slice(-4).join('\n');

  var invBtns = '';
  Object.keys(ITEMS).forEach(function(k) {
    var cnt = player.inventory[k];
    invBtns += '<button class="battle-btn" id="btn_' + k + '" ' +
      (cnt === 0 || battleLocked ? 'disabled' : '') + '>' +
      ITEMS[k].name + ' (' + cnt + ')</button>';
  });

  w.html(
    '<div class="game-container">' +
    '<div class="battle-screen">' +
    '<div class="enemy-area">' +
      '<div class="enemy-art">' + e.art + '</div>' +
      '<div class="enemy-name">' + e.name + '</div>' +
      '<div class="enemy-hp">HP: ' + e.hp + '/' + e.maxHp +
        ' <div class="hp-bar" style="width:120px;display:inline-block;vertical-align:middle">' +
        '<div class="hp-fill" style="background:#f00;width:' + hpPct + '%"></div></div></div>' +
      '<div style="color:#aaa;font-size:11px;margin-top:4px;font-style:italic">"' + e.desc + '"</div>' +
    '</div>' +
    '<div class="battle-log">' + logText + '</div>' +
    '<div class="battle-menu">' +
      '<button class="battle-btn" id="btn_fight"' + (battleLocked ? ' disabled' : '') + '>⚔ FIGHT</button>' +
      '<button class="battle-btn" id="btn_special"' + (battleLocked ? ' disabled' : '') + '>★ ZINGER</button>' +
      '<button class="battle-btn" id="btn_run"' + (battleLocked ? ' disabled' : '') + '>↩ RUN</button>' +
    '</div>' +
    '<div class="battle-menu">' + invBtns + '</div>' +
    '<div class="battle-status">' +
      'LVL:<span>' + player.level + '</span> ' +
      'HP:<span>' + player.hp + '/' + player.maxHp + '</span> ' +
      '<div class="hp-bar"><div class="hp-fill" style="width:' + phpPct + '%"></div></div> ' +
      'ATK:<span>' + player.atk + '</span> DEF:<span>' + player.def + '</span>' +
      statusHtml +
    '</div>' +
    '</div></div>'
  );

  $('#btn_fight').click(doFight);
  $('#btn_special').click(doSpecial);
  $('#btn_run').click(doRun);
  Object.keys(ITEMS).forEach(function(k) {
    $('#btn_' + k).click(function() { useItem(k); });
  });
}

/* ── BATTLE LOGIC ─────────────────────────────────────────────────────── */
function log(msg) { battleLog.push(msg); }

function lockBattle(ms, fn) {
  battleLocked = true;
  renderBattle();
  setTimeout(function() {
    battleLocked = false;
    fn();
  }, ms);
}

function enemyTurn() {
  var e = currentEnemy;

  // Phase 2 trigger for boss
  if (e.isBoss && !phase2Triggered && e.hp <= e.phase2Threshold) {
    phase2Triggered = true;
    log('');
    log('! ' + e.phase2Desc);
    e.atk += 5;
  }

  // Status tick
  if (player.statusEffect) {
    player.statusTurns--;
    if (player.statusTurns <= 0) {
      log('Your ' + player.statusEffect + ' wears off.');
      if (player.statusEffect === 'weakened') player.atk = Math.floor(player.atk * 2);
      if (player.statusEffect === 'debuffed') player.def = Math.floor(player.def * 2);
      player.statusEffect = null;
    }
  }

  if (player.statusEffect === 'stunned') {
    log('You are stonewalled and cannot act!');
    resolveEnemyAttack();
    return;
  }

  // Special move chance (25%)
  if (Math.random() < 0.25) {
    doEnemySpecial();
  } else {
    resolveEnemyAttack();
  }
}

function resolveEnemyAttack() {
  var e = currentEnemy;
  var atk = e.attacks[randomInt(0, e.attacks.length - 1)];
  var dmg = Math.max(1, e.atk - player.def + randomInt(-2, 3));
  player.hp -= dmg;
  log('Enemy ' + atk + '!');
  log('  You take ' + dmg + ' damage.');

  if (player.hp <= 0) {
    player.hp = 0;
    setTimeout(function() { screen = 'gameover'; render(); }, 800);
    return;
  }
  setTimeout(function() { battleLocked = false; renderBattle(); }, 400);
}

function doEnemySpecial() {
  var e = currentEnemy;
  log('! ' + e.name + ' uses ' + e.special + '!');
  log('  ' + e.specialDesc);

  if (e.special === 'Distract') {
    player.def = Math.max(1, player.def - 2);
    player.statusEffect = 'debuffed'; player.statusTurns = 2;
  } else if (e.special === 'Ticket Closed') {
    player.statusEffect = 'stunned'; player.statusTurns = 1;
  } else if (e.special === 'Paper Jam') {
    var dmg = 15; player.hp = Math.max(0, player.hp - dmg);
    log('  You take ' + dmg + ' damage from the paper jam!');
  } else if (e.special === 'Write-Up') {
    player.statusEffect = 'weakened'; player.statusTurns = 2;
    player.atk = Math.max(1, Math.floor(player.atk / 2));
  } else if (e.special === 'Action Item') {
    player.statusEffect = 'debuffed'; player.statusTurns = 2;
    player.def = Math.max(1, Math.floor(player.def / 2));
  } else if (e.special === 'Hovering') {
    var dmg1 = Math.max(1, e.atk - player.def + randomInt(-2, 3));
    var dmg2 = Math.max(1, e.atk - player.def + randomInt(-2, 3));
    player.hp -= (dmg1 + dmg2);
    log('  Attacks twice! ' + dmg1 + ' + ' + dmg2 + ' damage!');
  } else if (e.special === 'Downsizing') {
    var dmg = 25; player.hp = Math.max(0, player.hp - dmg);
    player.maxHp = Math.max(10, player.maxHp - 5);
    log('  You take ' + dmg + ' damage! Max HP reduced by 5!');
  }

  if (player.hp <= 0) {
    player.hp = 0;
    setTimeout(function() { screen = 'gameover'; render(); }, 800);
    return;
  }
  setTimeout(function() { battleLocked = false; renderBattle(); }, 600);
}

function doFight() {
  if (battleLocked) return;
  var e = currentEnemy;
  var dmg = Math.max(1, player.atk - e.def + randomInt(-3, 4));
  e.hp -= dmg;
  log('You attack ' + e.name + '!');
  log('  Dealt ' + dmg + ' damage.');

  if (e.hp <= 0) {
    e.hp = 0;
    battleWon();
    return;
  }
  lockBattle(600, enemyTurn);
}

function doSpecial() {
  if (battleLocked) return;
  var e = currentEnemy;
  // Zinger: roast the enemy - big damage but misses 30% of time
  log('You unleash a devastating ZINGER!');
  if (Math.random() < 0.3) {
    log('  ...crickets. It misses completely.');
    lockBattle(600, enemyTurn);
    return;
  }
  var zingers = [
    '"You know what? I\'m going to have to circle back on that."',
    '"Per my last email..."',
    '"As per our discussion..."',
    '"Let\'s take this offline."',
    '"Going forward..."',
    '"This is a great opportunity for growth."'
  ];
  var z = zingers[randomInt(0, zingers.length - 1)];
  var dmg = Math.max(1, player.atk * 2 - e.def + randomInt(0, 5));
  e.hp -= dmg;
  log('  ' + z);
  log('  Critical hit! ' + dmg + ' damage!');

  if (e.hp <= 0) {
    e.hp = 0;
    battleWon();
    return;
  }
  lockBattle(700, enemyTurn);
}

function doRun() {
  if (battleLocked) return;
  if (currentEnemy.isBoss) {
    log('The Boss blocks the door. "Where do you think you\'re going?"');
    lockBattle(700, enemyTurn);
    return;
  }
  if (Math.random() < 0.5) {
    log('You make an excuse and slip away!');
    setTimeout(function() {
      screen = 'map';
      mapMessage = 'You escaped!';
      newStepsToEncounter();
      render();
    }, 700);
  } else {
    log('You can\'t escape! (Too many witnesses.)');
    lockBattle(600, enemyTurn);
  }
}

function useItem(key) {
  if (battleLocked || player.inventory[key] <= 0) return;
  var item = ITEMS[key];
  var heal = Math.min(item.heal, player.maxHp - player.hp);
  player.hp += heal;
  player.inventory[key]--;
  log('You drink a ' + item.name + '!');
  log('  Restored ' + heal + ' Energy.');
  lockBattle(600, enemyTurn);
}

function battleWon() {
  battleLocked = true;
  var e = currentEnemy;
  log('');
  log('★ ' + e.name + ' has been defeated!');
  log('  +" + e.xp + " XP, +$' + e.gold);
  player.xp += e.xp;
  player.gold += e.gold;

  if (e.loot && Math.random() < 0.5) {
    player.inventory[e.loot] = (player.inventory[e.loot] || 0) + 1;
    log('  Found: ' + ITEMS[e.loot].name + '!');
  }

  if (e.isBoss) {
    bossDefeated = true;
    setTimeout(function() { screen = 'win'; render(); }, 1500);
    return;
  }

  renderBattle();

  if (checkLevelUp()) {
    setTimeout(function() { screen = 'levelup'; render(); }, 1000);
  } else {
    setTimeout(function() {
      screen = 'map';
      mapMessage = e.name + ' defeated! +' + e.xp + ' XP';
      newStepsToEncounter();
      render();
    }, 1200);
  }
}

/* ── MOVEMENT & ENCOUNTER ─────────────────────────────────────────────── */
function tryMove(dr, dc) {
  if (screen !== 'map') return;
  var nr = player.row + dr;
  var nc = player.col + dc;
  var ch = cellAt(nr, nc);

  if (!walkable(ch)) return;

  // Reached water cooler?
  if (ch === 'W') {
    if (!bossDefeated) {
      mapMessage = 'A shadowy figure blocks the water cooler. "You haven\'t earned this."';
      render();
      return;
    }
    screen = 'win';
    render();
    return;
  }

  player.row = nr;
  player.col = nc;
  mapMessage = '';

  // Encounter check
  stepsToEncounter--;
  if (stepsToEncounter <= 0) {
    newStepsToEncounter();
    var zone = zoneAt(nr, nc);

    // Only trigger boss encounter in boss area and if not defeated
    if (zone === 'boss_area' && !bossDefeated) {
      startBattle('the_boss');
      return;
    }

    // Random encounter
    if (zone !== 'boss_area') {
      var pool = ZONE_ENCOUNTERS[zone] || ZONE_ENCOUNTERS.office;
      var key = pool[randomInt(0, pool.length - 1)];
      startBattle(key);
      return;
    }
  }

  render();
}

function startBattle(key) {
  var template = ENEMIES[key];
  currentEnemy = Object.assign({}, template);
  currentEnemy.hp = template.hp;
  battleLog = [];
  phase2Triggered = false;
  battleLocked = false;
  log('A wild ' + currentEnemy.name + ' appears!');
  log('"' + currentEnemy.desc + '"');
  screen = 'battle';
  render();
}

/* ── SCREEN RENDERS ───────────────────────────────────────────────────── */
function renderTitle() {
  w.html(
    '<div class="game-container">' +
    '<div class="title-screen">' +
    '<div class="title-art">' +
    ' ___  ______ ______ ____  ___  _____\n' +
    '/ _ \\|  ____|  ____|_  _|/ __||  ___|\n' +
    '| | | | |__  | |__   | || |   | |__\n' +
    '| | | |  __| |  __|  | || |   |  __|\n' +
    '| |_| | |    | |    _| || |__ | |___\n' +
    ' \\___/|_|    |_|   |____\\____||_____|\n' +
    '             Q U E S T\n' +
    '</div>' +
    '<div style="color:#ff0;font-size:18px;font-weight:bold;margin-bottom:8px;">⚔ OFFICE QUEST ⚔</div>' +
    '<div class="title-sub">A Legend of the Cubicle Lands</div>' +
    '<div style="color:#aaa;font-size:12px;margin-bottom:20px;">' +
      'The water cooler awaits...<br>' +
      'But The Boss stands in your way.<br>' +
      'Survive the open office floor.<br>' +
      'Defeat the chatty coworkers.<br>' +
      'Reach the water cooler and win.' +
    '</div>' +
    '<button class="btn" id="btn_start">▶ BEGIN YOUR JOURNEY</button>' +
    '<div style="color:#555;font-size:11px;margin-top:15px;">Arrow keys to move &nbsp;|&nbsp; I to use items &nbsp;|&nbsp; Battle: click buttons</div>' +
    '</div></div>'
  );
  $('#btn_start').click(function() {
    screen = 'map';
    mapMessage = 'You arrive at the office. The water cooler is somewhere out there...';
    render();
  });
}

function renderLevelUp() {
  var g = lastLevelGains;
  w.html(
    '<div class="game-container">' +
    '<div class="levelup-screen">' +
    '<h2>★ LEVEL UP! ★</h2>' +
    '<p>You are now Level ' + player.level + '!</p>' +
    '<p style="color:#0f0">+' + g.hpGain + ' Max Energy &nbsp; +' + g.atkGain + ' Attack &nbsp; +' + g.defGain + ' Defense</p>' +
    '<p style="color:#aaa">HP: ' + player.hp + '/' + player.maxHp + ' &nbsp; ATK: ' + player.atk + ' &nbsp; DEF: ' + player.def + '</p>' +
    '<button class="btn" id="btn_continue">CONTINUE</button>' +
    '</div></div>'
  );
  $('#btn_continue').click(function() {
    screen = 'map';
    mapMessage = 'Level ' + player.level + '! You feel more experienced.';
    newStepsToEncounter();
    render();
  });
}

function renderGameOver() {
  w.html(
    '<div class="game-container">' +
    '<div class="gameover-screen">' +
    '<div class="gameover-art">THOU ART DEFEATED</div>' +
    '<div style="color:#f00;font-size:14px;margin-bottom:15px;">You\'ve been HR-processed out of the building.</div>' +
    '<div style="color:#aaa;font-size:13px;">' +
      'Level reached: ' + player.level + '<br>' +
      'Enemies slain: ' + player.gold + ' worth of petty cash recovered' +
    '</div>' +
    '<button class="btn" id="btn_restart">▶ TRY AGAIN</button>' +
    '</div></div>'
  );
  $('#btn_restart').click(function() {
    resetGame();
    screen = 'title';
    render();
  });
}

function renderWin() {
  w.html(
    '<div class="game-container">' +
    '<div class="win-screen">' +
    '<div class="win-art">★ VICTORY! ★</div>' +
    '<div style="color:#ff0;font-size:16px;margin-bottom:10px;">YOU REACHED THE WATER COOLER!</div>' +
    '<div style="color:#0ff;font-size:14px;margin-bottom:15px;">' +
      'After defeating The Boss and surviving the open office,<br>' +
      'you finally enjoy a refreshing cup of lukewarm water.<br>' +
      'It tastes like justice.' +
    '</div>' +
    '<div style="color:#aaa;font-size:13px;">' +
      'Final Level: ' + player.level + '<br>' +
      'Final HP: ' + player.hp + '/' + player.maxHp + '<br>' +
      'Gold collected: $' + player.gold +
    '</div>' +
    '<button class="btn" id="btn_restart">▶ PLAY AGAIN</button>' +
    '</div></div>'
  );
  $('#btn_restart').click(function() {
    resetGame();
    screen = 'title';
    render();
  });
}

/* ── RESET ────────────────────────────────────────────────────────────── */
function resetGame() {
  player.row = 1; player.col = 1;
  player.hp = 50; player.maxHp = 50;
  player.atk = 12; player.def = 5;
  player.level = 1; player.xp = 0; player.xpNext = 20;
  player.gold = 10;
  player.inventory = { coffee: 2, energy_drink: 0, donut: 1 };
  player.statusEffect = null; player.statusTurns = 0;
  bossDefeated = false;
  battleLog = [];
  phase2Triggered = false;
  newStepsToEncounter();
}

/* ── MAIN RENDER ──────────────────────────────────────────────────────── */
function render() {
  if (screen === 'title')    renderTitle();
  else if (screen === 'map') renderMap();
  else if (screen === 'battle') renderBattle();
  else if (screen === 'levelup') renderLevelUp();
  else if (screen === 'gameover') renderGameOver();
  else if (screen === 'win') renderWin();
}

/* ── KEYBOARD ─────────────────────────────────────────────────────────── */
$(document).off('keydown.oq').on('keydown.oq', function(e) {
  if (screen === 'map') {
    if (e.key === 'ArrowUp')    { e.preventDefault(); tryMove(-1, 0); }
    if (e.key === 'ArrowDown')  { e.preventDefault(); tryMove(1, 0); }
    if (e.key === 'ArrowLeft')  { e.preventDefault(); tryMove(0, -1); }
    if (e.key === 'ArrowRight') { e.preventDefault(); tryMove(0, 1); }
    if (e.key === 'i' || e.key === 'I') {
      var keys = Object.keys(player.inventory);
      for (var i = 0; i < keys.length; i++) {
        if (player.inventory[keys[i]] > 0 && player.hp < player.maxHp) {
          var item = ITEMS[keys[i]];
          var heal = Math.min(item.heal, player.maxHp - player.hp);
          player.hp += heal;
          player.inventory[keys[i]]--;
          mapMessage = 'Used ' + item.name + '! Restored ' + heal + ' Energy.';
          render();
          break;
        }
      }
    }
  }
});

render();
